<?php
session_start();$msg='';$ok=false;
if($_SERVER['REQUEST_METHOD']==='POST'){
$h=trim($_POST['host']);$n=trim($_POST['name']);$u=trim($_POST['user']);$p=$_POST['pass'];
try{$pdo=new PDO("mysql:host=$h;dbname=$n;charset=utf8mb4",$u,$p,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
$sql=["CREATE TABLE IF NOT EXISTS users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,is_admin TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB","CREATE TABLE IF NOT EXISTS rooms(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,description TEXT,price DECIMAL(12,2) NOT NULL,image VARCHAR(500),capacity INT NOT NULL DEFAULT 2,status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB","CREATE TABLE IF NOT EXISTS bookings(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NULL,room_id INT UNSIGNED NOT NULL,check_in DATE NOT NULL,check_out DATE NOT NULL,guests INT NOT NULL DEFAULT 1,total DECIMAL(12,2) NOT NULL DEFAULT 0,status ENUM('pending','confirmed','cancelled','completed') DEFAULT 'pending',payment_status ENUM('unpaid','pending','paid') DEFAULT 'unpaid',guest_name VARCHAR(150) NOT NULL,phone VARCHAR(40) NOT NULL,notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(room_id),INDEX(check_in,check_out)) ENGINE=InnoDB","CREATE TABLE IF NOT EXISTS settings(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(100) UNIQUE,setting_value TEXT) ENGINE=InnoDB"];
foreach($sql as $q)$pdo->exec($q);$count=$pdo->query('SELECT COUNT(*) FROM rooms')->fetchColumn();if(!$count){$s=$pdo->prepare('INSERT INTO rooms(name,description,price,image,capacity) VALUES(?,?,?,?,?)');$rs=[['Deluxe Room','King bed, private bathroom, work desk and complimentary Wi-Fi.',180000,'https://images.unsplash.com/photo-1590490360182-c33d57733427?auto=format&fit=crop&w=1000&q=85',2],['Executive Suite','Spacious suite with lounge area, premium bedding and city views.',280000,'https://images.unsplash.com/photo-1591088398332-8a7791972843?auto=format&fit=crop&w=1000&q=85',3],['Family Room','Comfortable family layout with extra sleeping space and breakfast option.',240000,'https://images.unsplash.com/photo-1584132967334-10e028bd69f7?auto=format&fit=crop&w=1000&q=85',4]];foreach($rs as $r)$s->execute($r);}$s=$pdo->prepare("INSERT IGNORE INTO users(name,email,password,is_admin) VALUES('Hotel Administrator','admin@serenovahotel.co.tz',?,1)");$s->execute([password_hash('Admin@12345',PASSWORD_DEFAULT)]);file_put_contents(__DIR__.'/hotel-config.php',"<?php\ndefine('DB_HOST',".var_export($h,true).");\ndefine('DB_NAME',".var_export($n,true).");\ndefine('DB_USER',".var_export($u,true).");\ndefine('DB_PASS',".var_export($p,true).");\n");$ok=true;$msg='Installation complete. Login with admin@serenovahotel.co.tz and the temporary password Admin@12345, then change it.';}catch(Throwable $e){$msg='Database error: '.$e->getMessage();}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Serenova Setup</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><div class="container py-5" style="max-width:650px"><div class="card shadow-sm"><div class="card-body p-4"><h1>Serenova Hotel Setup</h1><p class="text-muted">Enter the MySQL database details from your hosting account.</p><?php if($msg):?><div class="alert alert-<?=$ok?'success':'danger'?>"><?=htmlspecialchars($msg)?></div><?php endif;?><form method="post"><label>Database Host</label><input name="host" class="form-control mb-3" value="localhost" required><label>Database Name</label><input name="name" class="form-control mb-3" required><label>Database Username</label><input name="user" class="form-control mb-3" required><label>Database Password</label><input name="pass" type="password" class="form-control mb-3"><button class="btn btn-dark w-100">Install Hotel System</button></form></div></div></div></body></html>